<script setup>
import {s,canEdit,run,stageFile,stageSheet,aiMapping,previewData,commitData,toggleSync,sync,dateText,number} from './store';
</script><template><section class="stack"><div v-if="!canEdit" class="notice">Bạn có quyền xem. Liên hệ Admin sự kiện để được cấp quyền chỉnh sửa.</div><div class="card stack"><h3>Nguồn dữ liệu hiện tại</h3><p>{{s.event.source?'Google Sheet':'File Excel / CSV'}} · Kiểm tra lần cuối: {{dateText(s.event.synced_at)}}</p><p v-if="s.event.sync_error" class="error">{{s.event.sync_error}}</p><div v-if="s.event.source" class="row"><MSwitch :model-value="s.event.source.enabled" :disabled="!canEdit||s.busy" @update:model-value="run(()=>toggleSync($event))"/><span>Tự động kiểm tra mỗi 5 phút</span><MButton v-if="canEdit" variant="secondary" :loading="s.busy" @click="run(sync)">Đồng bộ ngay</MButton></div></div>
<div v-if="canEdit" class="card stack"><h3>Nhập dữ liệu mới</h3><div class="grid-form"><label class="field">Tên tab (để trống dùng tab mặc định)<MInput v-model="s.sheetName" /></label><label class="field">Dòng tiêu đề<MInput v-model="s.headerRow" /></label></div><MUpload accept=".xlsx,.csv" :multiple="false" :max-size-m-b="10" :disabled="s.busy" label="Chọn file Excel hoặc CSV" @select-files="run(()=>stageFile($event))" @oversized="s.error='File tối đa 10 MB.'" /><label class="field">Link Google Sheet<MInput v-model="s.sheetUrl" placeholder="https://docs.google.com/spreadsheets/..." /></label><div class="row justify-end"><MButton variant="primary" :loading="s.busy" @click="run(stageSheet)">Đọc Google Sheet</MButton></div></div>
<div v-if="s.stage&&canEdit" class="card stack"><div class="toolbar"><h3>Ghép cột · {{number(s.stage.count)}} dòng</h3><MButton variant="secondary" :loading="s.busy" @click="run(aiMapping)">Gợi ý bằng Gemini</MButton></div><p class="muted">{{s.stage.discovery?.notice||'Đã nhận diện các cột nguồn khách.'}}</p><div class="grid-form"><label v-for="(label,key) in s.user.fields" :key="key" class="field">{{label}}<MCombobox v-model="s.mapping[key]" :options="[{label:'Không có cột',value:''},...s.stage.headers.map(h=>({value:h,label:h}))]" @change="s.preview=null" /></label></div><label class="field">Các cột dùng lọc nguồn khách (tối đa 12)<MCombobox v-model="s.sourceColumns" multiple :options="s.stage.headers.map(h=>({value:h,label:h}))" @change="s.preview=null" /></label><MCheckbox v-model="s.autoSync" label="Tự đồng bộ nếu nguồn là Google Sheet"/><div v-if="s.preview" class="notice">Xem trước: {{number(s.preview.summary.total)}} đăng ký, {{number(s.preview.summary.clevel)}} C-Level, {{number(s.preview.quality.invalidDates)}} ngày không hợp lệ. Dữ liệu chưa có hình thức sẽ là Chưa xác định.</div><div class="row justify-end"><MButton variant="secondary" :loading="s.busy" @click="run(previewData)">Kiểm tra dữ liệu</MButton><MButton variant="primary" :loading="s.busy" :disabled="!s.preview" @click="run(commitData)">Nhập dữ liệu</MButton></div></div></section></template>
